func buildChildThenLoader[Q orm.Loadable]() childThenLoader[Q] {
	type FlightsLoadInterface interface {
		LoadFlights(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return childThenLoader[Q]{
		Flights: thenLoadBuilder[Q](
			"Flights",
			func(ctx context.Context, exec bob.Executor, retrieved FlightsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadFlights(ctx, exec, mods...)
			},
		),
	}
}

// LoadFlights loads the child's Flights into the .R struct
func (o *Child) LoadFlights(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Flights = nil
	o.R.Loaded.Flights = false

	related, err := o.Flights(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Child = o
		rel.R.Loaded.Child = true
	}

	o.R.Flights = related
	o.R.Loaded.Flights = true
	return nil
}

// LoadFlights loads the child's Flights into the .R struct
func (os ChildSlice) LoadFlights(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	flights, err := os.Flights(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Flights = nil
		o.R.Loaded.Flights = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	childByKey := make(map[uuid.UUID][]*Child, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		childByKey[o.ID] = append(childByKey[o.ID], o)
	}

	for _, rel := range flights {

		owners, ok := childByKey[rel.ChildID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Child = o
			rel.R.Loaded.Child = true

			o.R.Flights = append(o.R.Flights, rel)

		}
	}

	return nil
}

// childC is where relationship counts are stored.
type childC struct {
	Flights *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Child) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Flights":
		o.C.Flights = &count
	}
	return nil
}

type childCountPreloader struct {
	Flights func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildChildCountPreloader() childCountPreloader {
	return childCountPreloader{
		Flights: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Child]("Flights", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Children.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Flights.NameAsExpr()),
					sm.Where(psql.Quote(Flights.Alias(), "child_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type childCountThenLoader[Q orm.Loadable] struct {
	Flights func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildChildCountThenLoader[Q orm.Loadable]() childCountThenLoader[Q] {
	type FlightsCountInterface interface {
		LoadCountFlights(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return childCountThenLoader[Q]{
		Flights: countThenLoadBuilder[Q](
			"Flights",
			func(ctx context.Context, exec bob.Executor, retrieved FlightsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountFlights(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountFlights loads the count of Flights into the C struct
func (o *Child) LoadCountFlights(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Flights(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Flights = &count
	return nil
}

// LoadCountFlights loads the count of Flights for a slice in a single batch query
func (os ChildSlice) LoadCountFlights(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "uuid[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			Flights.Columns.ChildID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(Flights.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(Flights.Columns.ChildID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(Flights.Columns.ChildID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[uuid.UUID]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.Flights = &count
	}

	return nil
}

type childJoins[Q dialect.Joinable] struct {
	typ     string
	Flights modAs[Q, flightColumns]
}

func (j childJoins[Q]) aliasedAs(alias string) childJoins[Q] {
	return buildChildJoins[Q](buildChildColumns(alias), j.typ)
}

func buildChildJoins[Q dialect.Joinable](cols childColumns, typ string) childJoins[Q] {
	return childJoins[Q]{
		typ: typ,
		Flights: modAs[Q, flightColumns]{
			c: Flights.Columns,
			f: func(to flightColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Flights.NameExpr().As(to.Alias())).On(
						to.ChildID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
